#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> parent(n), start(n + 1, 0), child(max(n - 1, 0));
    for (auto &x : parent) cin >> x;
    // Children lists (CSR); filling v = 1..n-1 in order keeps them ascending.
    for (int v = 1; v < n; v++) start[parent[v] + 1]++;
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    vector<int> fill(start.begin(), start.end() - 1);
    for (int v = 1; v < n; v++) child[fill[parent[v]]++] = v;
    // Iterative preorder DFS; phase 1 marks leaving a node so its subtree size is known.
    vector<int> tour, tin(n), size(n);
    tour.reserve(n);
    vector<pair<int, int>> stack = {{0, 0}};
    while (!stack.empty()) {
        auto [u, phase] = stack.back();
        stack.pop_back();
        if (phase == 0) {
            tin[u] = tour.size();
            tour.push_back(u);
            stack.push_back({u, 1});
            for (int i = start[u + 1] - 1; i >= start[u]; i--) stack.push_back({child[i], 0});
        } else {
            size[u] = tour.size() - tin[u];
        }
    }
    int q;
    cin >> q;
    string out;
    for (int i = 0; i < q; i++) {
        long long p, k;
        cin >> p >> k;
        // The subtree of p is the contiguous block tour[tin[p] .. tin[p] + size[p] - 1].
        long long ans = (1 <= k && k <= size[p]) ? tour[tin[p] + k - 1] : -1;
        if (i) out += ' ';
        out += to_string(ans);
    }
    cout << out << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] parent = new int[n], start = new int[n + 1], child = new int[Math.max(n - 1, 0)];
        for (int i = 0; i < n; i++) parent[i] = nextInt();
        // Children lists (CSR); filling v = 1..n-1 in order keeps them ascending.
        for (int v = 1; v < n; v++) start[parent[v] + 1]++;
        for (int i = 0; i < n; i++) start[i + 1] += start[i];
        int[] fill = Arrays.copyOf(start, n);
        for (int v = 1; v < n; v++) child[fill[parent[v]]++] = v;
        // Iterative preorder DFS; phase 1 marks leaving a node so its subtree size is known.
        int[] tour = new int[n], tin = new int[n], size = new int[n];
        int len = 0;
        int[] stack = new int[2 * n + 2]; // encoded as node * 2 + phase
        int top = 0;
        stack[top++] = 0;
        while (top > 0) {
            int e = stack[--top], u = e >> 1;
            if ((e & 1) == 0) {
                tin[u] = len;
                tour[len++] = u;
                stack[top++] = u * 2 + 1;
                for (int i = start[u + 1] - 1; i >= start[u]; i--) stack[top++] = child[i] * 2;
            } else {
                size[u] = len - tin[u];
            }
        }
        int q = nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int p = nextInt();
            long k = nextLong();
            // The subtree of p is the contiguous block tour[tin[p] .. tin[p] + size[p] - 1].
            long ans = (1 <= k && k <= size[p]) ? tour[tin[p] + (int) k - 1] : -1;
            if (i > 0) sb.append(' ');
            sb.append(ans);
        }
        System.out.println(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	parent := make([]int, n)
	for i := range parent {
		parent[i] = int(nextInt())
	}
	// Children lists (CSR); filling v = 1..n-1 in order keeps them ascending.
	start := make([]int, n+1)
	for v := 1; v < n; v++ {
		start[parent[v]+1]++
	}
	for i := 0; i < n; i++ {
		start[i+1] += start[i]
	}
	fill := append([]int(nil), start[:n]...)
	child := make([]int, max(n-1, 0))
	for v := 1; v < n; v++ {
		child[fill[parent[v]]] = v
		fill[parent[v]]++
	}
	// Iterative preorder DFS; phase 1 marks leaving a node so its subtree size is known.
	tour := make([]int, 0, n)
	tin := make([]int, n)
	size := make([]int, n)
	stack := []int{0} // encoded as node*2 + phase
	for len(stack) > 0 {
		e := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		u := e >> 1
		if e&1 == 0 {
			tin[u] = len(tour)
			tour = append(tour, u)
			stack = append(stack, u*2+1)
			for i := start[u+1] - 1; i >= start[u]; i-- {
				stack = append(stack, child[i]*2)
			}
		} else {
			size[u] = len(tour) - tin[u]
		}
	}
	q := int(nextInt())
	var out []byte
	for i := 0; i < q; i++ {
		p, k := int(nextInt()), nextInt()
		// The subtree of p is the contiguous block tour[tin[p] .. tin[p] + size[p] - 1].
		ans := int64(-1)
		if 1 <= k && k <= int64(size[p]) {
			ans = int64(tour[tin[p]+int(k)-1])
		}
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, ans, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
